window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fa9a4bf8316465c1"]={"versions": [{"id": "FIG-fa9a4bf8316465c1", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm / Struktur- und Abhängigkeitsdiagramm (Component & Interface Dependency Diagram).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R21-11), Spezifikation <code>AUTOSAR_EXP_SWArchitecture</code>.</li>\n<li><strong>Technischer Zweck:</strong> Dokumentation der minimalen externen Plattform- und Betriebssystemabhängigkeiten des Functional Clusters <strong>Registry</strong>. Das Diagramm definiert, dass die Registry zur Zustandssicherung nicht auf andere High-Level-Cluster (wie <code>ara::per</code>), sondern direkt auf eine interne, vom zugrundeliegenden Betriebssystem bereitgestellte nicht-flüchtige Speicherschnittstelle aufsetzt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>«aapFunctionalCluster» Registry:</strong></li>\n<li>Logischer Funktionscluster der AUTOSAR Adaptive Platform (Plattformebene).</li>\n<li>Verwaltet Registrierungs- und Zuordnungsdaten (z. B. Service-/Instanzregistrierungen, Konfigurations- oder Identitätsmappings).</li>\n<li><strong>«aapInternal» Non-volatile Storage:</strong></li>\n<li>Stereotyp <code>«aapInternal»</code>: Markiert eine plattforminterne Schnittstellenabstraktion, die nicht als öffentliches C++-API (<code>ara::*</code>) für reguläre Adaptive Applications exponiert ist.</li>\n<li>Stellt Abstraktionen für nicht-flüchtigen Speicherzugriff bereit (Schreiben, Lesen, Persistieren von Registry-Datensätzen).</li>\n<li><strong>Operating System:</strong></li>\n<li>Basiskomponente der Adaptive-Laufzeitumgebung (in der Regel POSIX-konformes PSE51/PSE52/PSE53-kompatibles Betriebssystem inkl. Hardware-Treiber).</li>\n<li><strong>Beziehungen:</strong></li>\n<li><code>Registry</code> $\\rightarrow$ <code>Non-volatile Storage</code>: UML-Abhängigkeit (<code>«use»</code>, gestrichelte Linie mit offener Pfeilspitze). Die Registry konsumiert die Speicherschnittstelle.</li>\n<li><code>Operating System</code> $\\rightarrow$ <code>Non-volatile Storage</code>: UML-Schnittstellenrealisierung (Interface Realization, gestrichelte Linie mit geschlossener, nicht ausgefüllter Dreiecksspitze). Das Betriebssystem implementiert die geforderte nicht-flüchtige Speicherfunktionalität (z. B. über POSIX-Dateisysteme, Flash-/NVRAM-Treiber oder Blockdevices).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammcharakter:</strong> Rein statisches Struktur- und Schnittstellenmodell; enthält keine explizite zeitliche Sequenzabfolge.</li>\n<li><strong>Impliziter Laufzeitablauf:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Boot-/Initialisierungsphase:</em> Die Registry liest während des Startups (orchestriert durch Execution Management) zuvor persistierte Datensätze synchron über die interne OS-Speicherschnittstelle ein, um den Registry-Zustand wiederherzustellen.</li>\n<li><em>Laufzeitaktualisierung:</em> Bei Zustandsänderungen, Neuregistrierungen oder Updates persistiert die Registry kritische Daten über synchrone oder asynchrone OS-Storage-Aufrufe (z. B. File-I/O mit anschließendem <code>fsync()</code> / Flush), um Power-Fail-Sicherheit über Boot-Zyklen hinweg zu gewährleisten.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Keine <code>ara::per</code>-Zirkularität:</strong> Die Registry nutzt bewusst nicht den Persistency-Cluster (<code>ara::per</code>), um Henne-Ei-Probleme und zirkuläre Initialisierungsabhängigkeiten beim Platform-Bootstrap zu vermeiden.</li>\n<li><strong>Plattform- & OS-Integratoren:</strong></li>\n<li>Das eingesetzte POSIX-Betriebssystem muss eine robuste, ausfallsichere Speicherpartition (Flash/eMMC/SSD) bereitstellen, auf die der Registry-Prozess zugreifen kann.</li>\n<li>Zugriffsrechte (DAC/MAC, z. B. SELinux-Policies) müssen so konfiguriert werden, dass der Registry-Daemon Lese- und Schreibberechtigung auf die zugehörigen Pfade/Block-Devices besitzt.</li>\n<li><strong>Applikations-Entwickler:</strong></li>\n<li>Die Schnittstelle <code>Non-volatile Storage</code> ist intern (<code>«aapInternal»</code>) und für Adaptive Applications weder sichtbar noch direkt bindbar.</li>\n<li>Standard-Applikationen interagieren ausschließlich über die standardisierten Service-Interfaces mit der Registry.</li>\n</ul>"}, {"id": "FIG-1b20c97129713a25", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm / Struktur- und Abhängigkeitsdiagramm (Component & Interface Dependency Diagram).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R21-11), Spezifikation <code>AUTOSAR_EXP_SWArchitecture</code>.</li>\n<li><strong>Technischer Zweck:</strong> Dokumentation der minimalen externen Plattform- und Betriebssystemabhängigkeiten des Functional Clusters <strong>Registry</strong>. Das Diagramm definiert, dass die Registry zur Zustandssicherung nicht auf andere High-Level-Cluster (wie <code>ara::per</code>), sondern direkt auf eine interne, vom zugrundeliegenden Betriebssystem bereitgestellte nicht-flüchtige Speicherschnittstelle aufsetzt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>«aapFunctionalCluster» Registry:</strong></li>\n<li>Logischer Funktionscluster der AUTOSAR Adaptive Platform (Plattformebene).</li>\n<li>Verwaltet Registrierungs- und Zuordnungsdaten (z. B. Service-/Instanzregistrierungen, Konfigurations- oder Identitätsmappings).</li>\n<li><strong>«aapInternal» Non-volatile Storage:</strong></li>\n<li>Stereotyp <code>«aapInternal»</code>: Markiert eine plattforminterne Schnittstellenabstraktion, die nicht als öffentliches C++-API (<code>ara::*</code>) für reguläre Adaptive Applications exponiert ist.</li>\n<li>Stellt Abstraktionen für nicht-flüchtigen Speicherzugriff bereit (Schreiben, Lesen, Persistieren von Registry-Datensätzen).</li>\n<li><strong>Operating System:</strong></li>\n<li>Basiskomponente der Adaptive-Laufzeitumgebung (in der Regel POSIX-konformes PSE51/PSE52/PSE53-kompatibles Betriebssystem inkl. Hardware-Treiber).</li>\n<li><strong>Beziehungen:</strong></li>\n<li><code>Registry</code> $\\rightarrow$ <code>Non-volatile Storage</code>: UML-Abhängigkeit (<code>«use»</code>, gestrichelte Linie mit offener Pfeilspitze). Die Registry konsumiert die Speicherschnittstelle.</li>\n<li><code>Operating System</code> $\\rightarrow$ <code>Non-volatile Storage</code>: UML-Schnittstellenrealisierung (Interface Realization, gestrichelte Linie mit geschlossener, nicht ausgefüllter Dreiecksspitze). Das Betriebssystem implementiert die geforderte nicht-flüchtige Speicherfunktionalität (z. B. über POSIX-Dateisysteme, Flash-/NVRAM-Treiber oder Blockdevices).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammcharakter:</strong> Rein statisches Struktur- und Schnittstellenmodell; enthält keine explizite zeitliche Sequenzabfolge.</li>\n<li><strong>Impliziter Laufzeitablauf:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Boot-/Initialisierungsphase:</em> Die Registry liest während des Startups (orchestriert durch Execution Management) zuvor persistierte Datensätze synchron über die interne OS-Speicherschnittstelle ein, um den Registry-Zustand wiederherzustellen.</li>\n<li><em>Laufzeitaktualisierung:</em> Bei Zustandsänderungen, Neuregistrierungen oder Updates persistiert die Registry kritische Daten über synchrone oder asynchrone OS-Storage-Aufrufe (z. B. File-I/O mit anschließendem <code>fsync()</code> / Flush), um Power-Fail-Sicherheit über Boot-Zyklen hinweg zu gewährleisten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Keine <code>ara::per</code>-Zirkularität:</strong> Die Registry nutzt bewusst nicht den Persistency-Cluster (<code>ara::per</code>), um Henne-Ei-Probleme und zirkuläre Initialisierungsabhängigkeiten beim Platform-Bootstrap zu vermeiden.</li>\n<li><strong>Plattform- & OS-Integratoren:</strong></li>\n<li>Das eingesetzte POSIX-Betriebssystem muss eine robuste, ausfallsichere Speicherpartition (Flash/eMMC/SSD) bereitstellen, auf die der Registry-Prozess zugreifen kann.</li>\n<li>Zugriffsrechte (DAC/MAC, z. B. SELinux-Policies) müssen so konfiguriert werden, dass der Registry-Daemon Lese- und Schreibberechtigung auf die zugehörigen Pfade/Block-Devices besitzt.</li>\n<li><strong>Applikations-Entwickler:</strong></li>\n<li>Die Schnittstelle <code>Non-volatile Storage</code> ist intern (<code>«aapInternal»</code>) und für Adaptive Applications weder sichtbar noch direkt bindbar.</li>\n<li>Standard-Applikationen interagieren ausschließlich über die standardisierten Service-Interfaces mit der Registry.</li>\n</ul>"}, {"id": "FIG-1a19cdbc5fa8899b", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm / Struktur- und Abhängigkeitsdiagramm (Component & Interface Dependency Diagram).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R21-11), Spezifikation <code>AUTOSAR_EXP_SWArchitecture</code>.</li>\n<li><strong>Technischer Zweck:</strong> Dokumentation der minimalen externen Plattform- und Betriebssystemabhängigkeiten des Functional Clusters <strong>Registry</strong>. Das Diagramm definiert, dass die Registry zur Zustandssicherung nicht auf andere High-Level-Cluster (wie <code>ara::per</code>), sondern direkt auf eine interne, vom zugrundeliegenden Betriebssystem bereitgestellte nicht-flüchtige Speicherschnittstelle aufsetzt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Registry:</strong></li>\n<li>Logische Plattformkomponente der AUTOSAR Adaptive Platform (Plattformebene).</li>\n<li>Verwaltet Registrierungs- und Zuordnungsdaten (z. B. Service-/Instanzregistrierungen, Konfigurations- oder Identitätsmappings).</li>\n<li><strong>«aapInternal» Non-volatile Storage:</strong></li>\n<li>Stereotyp <code>«aapInternal»</code>: Markiert eine plattforminterne Schnittstellenabstraktion, die nicht als öffentliches C++-API (<code>ara::*</code>) für reguläre Adaptive Applications exponiert ist.</li>\n<li>Stellt Abstraktionen für nicht-flüchtigen Speicherzugriff bereit (Schreiben, Lesen, Persistieren von Registry-Datensätzen).</li>\n<li><strong>Operating System:</strong></li>\n<li>Basiskomponente der Adaptive-Laufzeitumgebung (in der Regel POSIX-konformes PSE51/PSE52/PSE53-kompatibles Betriebssystem inkl. Hardware-Treiber).</li>\n<li><strong>Beziehungen:</strong></li>\n<li><code>Registry</code> $\\rightarrow$ <code>Non-volatile Storage</code>: UML-Abhängigkeit (<code>«use»</code>, gestrichelte Linie mit offener Pfeilspitze). Die Registry konsumiert die Speicherschnittstelle.</li>\n<li><code>Operating System</code> $\\rightarrow$ <code>Non-volatile Storage</code>: UML-Schnittstellenrealisierung (Interface Realization, gestrichelte Linie mit geschlossener, nicht ausgefüllter Dreiecksspitze). Das Betriebssystem implementiert die geforderte nicht-flüchtige Speicherfunktionalität (z. B. über POSIX-Dateisysteme, Flash-/NVRAM-Treiber oder Blockdevices).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammcharakter:</strong> Rein statisches Struktur- und Schnittstellenmodell; enthält keine explizite zeitliche Sequenzabfolge.</li>\n<li><strong>Impliziter Laufzeitablauf:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Boot-/Initialisierungsphase:</em> Die Registry liest während des Startups (orchestriert durch Execution Management) zuvor persistierte Datensätze synchron über die interne OS-Speicherschnittstelle ein, um den Registry-Zustand wiederherzustellen.</li>\n<li><em>Laufzeitaktualisierung:</em> Bei Zustandsänderungen, Neuregistrierungen oder Updates persistiert die Registry kritische Daten über synchrone oder asynchrone OS-Storage-Aufrufe (z. B. File-I/O mit anschließendem <code>fsync()</code> / Flush), um Power-Fail-Sicherheit über Boot-Zyklen hinweg zu gewährleisten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Keine <code>ara::per</code>-Zirkularität:</strong> Die Registry nutzt bewusst nicht den Persistency-Cluster (<code>ara::per</code>), um Henne-Ei-Probleme und zirkuläre Initialisierungsabhängigkeiten beim Platform-Bootstrap zu vermeiden.</li>\n<li><strong>Plattform- & OS-Integratoren:</strong></li>\n<li>Das eingesetzte POSIX-Betriebssystem muss eine robuste, ausfallsichere Speicherpartition (Flash/eMMC/SSD) bereitstellen, auf die der Registry-Prozess zugreifen kann.</li>\n<li>Zugriffsrechte (DAC/MAC, z. B. SELinux-Policies) müssen so konfiguriert werden, dass der Registry-Daemon Lese- und Schreibberechtigung auf die zugehörigen Pfade/Block-Devices besitzt.</li>\n<li><strong>Applikations-Entwickler:</strong></li>\n<li>Die Schnittstelle <code>Non-volatile Storage</code> ist intern (<code>«aapInternal»</code>) und für Adaptive Applications weder sichtbar noch direkt bindbar.</li>\n<li>Standard-Applikationen interagieren ausschließlich über die standardisierten Service-Interfaces mit der Registry.</li>\n</ul>"}, {"id": "FIG-c9bf6ae61c5c0b3b", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm / Struktur- und Abhängigkeitsdiagramm (Component & Interface Dependency Diagram).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R21-11), Spezifikation <code>AUTOSAR_EXP_SWArchitecture</code>.</li>\n<li><strong>Technischer Zweck:</strong> Dokumentation der minimalen externen Plattform- und Betriebssystemabhängigkeiten des Functional Clusters <strong>Registry</strong>. Das Diagramm definiert, dass die Registry zur Zustandssicherung nicht auf andere High-Level-Cluster (wie <code>ara::per</code>), sondern direkt auf eine interne, vom zugrundeliegenden Betriebssystem bereitgestellte nicht-flüchtige Speicherschnittstelle aufsetzt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Registry:</strong></li>\n<li>Logische Plattformkomponente der AUTOSAR Adaptive Platform (Plattformebene).</li>\n<li>Verwaltet Registrierungs- und Zuordnungsdaten (z. B. Service-/Instanzregistrierungen, Konfigurations- oder Identitätsmappings).</li>\n<li><strong>«aapInternal» Non-volatile Storage:</strong></li>\n<li>Stereotyp <code>«aapInternal»</code>: Markiert eine plattforminterne Schnittstellenabstraktion, die nicht als öffentliches C++-API (<code>ara::*</code>) für reguläre Adaptive Applications exponiert ist.</li>\n<li>Stellt Abstraktionen für nicht-flüchtigen Speicherzugriff bereit (Schreiben, Lesen, Persistieren von Registry-Datensätzen).</li>\n<li><strong>Operating System:</strong></li>\n<li>Basiskomponente der Adaptive-Laufzeitumgebung (in der Regel POSIX-konformes PSE51/PSE52/PSE53-kompatibles Betriebssystem inkl. Hardware-Treiber).</li>\n<li><strong>Beziehungen:</strong></li>\n<li><code>Registry</code> $\\rightarrow$ <code>Non-volatile Storage</code>: UML-Abhängigkeit (<code>«use»</code>, gestrichelte Linie mit offener Pfeilspitze). Die Registry konsumiert die Speicherschnittstelle.</li>\n<li><code>Operating System</code> $\\rightarrow$ <code>Non-volatile Storage</code>: UML-Schnittstellenrealisierung (Interface Realization, gestrichelte Linie mit geschlossener, nicht ausgefüllter Dreiecksspitze). Das Betriebssystem implementiert die geforderte nicht-flüchtige Speicherfunktionalität (z. B. über POSIX-Dateisysteme, Flash-/NVRAM-Treiber oder Blockdevices).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammcharakter:</strong> Rein statisches Struktur- und Schnittstellenmodell; enthält keine explizite zeitliche Sequenzabfolge.</li>\n<li><strong>Impliziter Laufzeitablauf:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Boot-/Initialisierungsphase:</em> Die Registry liest während des Startups (orchestriert durch Execution Management) zuvor persistierte Datensätze synchron über die interne OS-Speicherschnittstelle ein, um den Registry-Zustand wiederherzustellen.</li>\n<li><em>Laufzeitaktualisierung:</em> Bei Zustandsänderungen, Neuregistrierungen oder Updates persistiert die Registry kritische Daten über synchrone oder asynchrone OS-Storage-Aufrufe (z. B. File-I/O mit anschließendem <code>fsync()</code> / Flush), um Power-Fail-Sicherheit über Boot-Zyklen hinweg zu gewährleisten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Keine <code>ara::per</code>-Zirkularität:</strong> Die Registry nutzt bewusst nicht den Persistency-Cluster (<code>ara::per</code>), um Henne-Ei-Probleme und zirkuläre Initialisierungsabhängigkeiten beim Platform-Bootstrap zu vermeiden.</li>\n<li><strong>Plattform- & OS-Integratoren:</strong></li>\n<li>Das eingesetzte POSIX-Betriebssystem muss eine robuste, ausfallsichere Speicherpartition (Flash/eMMC/SSD) bereitstellen, auf die der Registry-Prozess zugreifen kann.</li>\n<li>Zugriffsrechte (DAC/MAC, z. B. SELinux-Policies) müssen so konfiguriert werden, dass der Registry-Daemon Lese- und Schreibberechtigung auf die zugehörigen Pfade/Block-Devices besitzt.</li>\n<li><strong>Applikations-Entwickler:</strong></li>\n<li>Die Schnittstelle <code>Non-volatile Storage</code> ist intern (<code>«aapInternal»</code>) und für Adaptive Applications weder sichtbar noch direkt bindbar.</li>\n<li>Standard-Applikationen interagieren ausschließlich über die standardisierten Service-Interfaces mit der Registry.</li>\n</ul>"}], "trans": [{"from": "FIG-fa9a4bf8316465c1", "to": "FIG-1b20c97129713a25", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1b20c97129713a25", "to": "FIG-1a19cdbc5fa8899b", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>Registry</code>: Stereotyp <code>«aapFunctionalCluster»</code> entfernt.</li>\n<li><code>Registry</code>: Hintergrundfarbe der Komponente von Orange auf Hellbeige geändert (Angleichung an die Standard-Komponentendarstellung ohne explizite Auszeichnung als Functional Cluster).</li>\n</ul>"}, {"from": "FIG-1a19cdbc5fa8899b", "to": "FIG-c9bf6ae61c5c0b3b", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
